node -e "
const { Client } = require('pg');
const client = new Client({ connectionString: process.env.DB_URL });
client.connect().then(async () => {
  console.log('Conectado ao RDS');

  // Verificar se o enum já existe
  const chkEnum = await client.query(\"SELECT 1 FROM pg_type WHERE typname = 'UserStatus'\");
  if (chkEnum.rows.length > 0) { console.log('Enum UserStatus ja existe'); }
  else {
    await client.query(\"CREATE TYPE \\\"UserStatus\\\" AS ENUM ('PENDING', 'ACTIVE', 'SUSPENDED')\");
    console.log('Enum UserStatus criado');
  }

  // Verificar se a coluna já existe
  const chkCol = await client.query(\"SELECT 1 FROM information_schema.columns WHERE table_name='User' AND column_name='status'\");
  if (chkCol.rows.length > 0) { console.log('Coluna status ja existe'); }
  else {
    await client.query(\"ALTER TABLE \\\"User\\\" ADD COLUMN status \\\"UserStatus\\\"\");
    await client.query(\"UPDATE \\\"User\\\" SET status = 'ACTIVE'\");
    await client.query(\"ALTER TABLE \\\"User\\\" ALTER COLUMN status SET NOT NULL\");
    await client.query(\"ALTER TABLE \\\"User\\\" ALTER COLUMN status SET DEFAULT 'PENDING'\");
    console.log('Coluna status adicionada e populada');
  }

  // Registar no _prisma_migrations para o migrate deploy ficar sincronizado
  const chkMig = await client.query(\"SELECT 1 FROM _prisma_migrations WHERE migration_name = '20260329000000_add_user_status'\");
  if (chkMig.rows.length === 0) {
    await client.query(\"INSERT INTO _prisma_migrations (id, checksum, finished_at, migration_name, logs, rolled_back_at, started_at, applied_steps_count) VALUES (gen_random_uuid()::text, 'manual', NOW(), '20260329000000_add_user_status', NULL, NULL, NOW(), 1)\");
    console.log('Migration registada no _prisma_migrations');
  }

  console.log('DONE');
  await client.end();
}).catch(e => { console.error(e.message); process.exit(1); });
